artifacts.content:
{
  "name": "<YOUR_APP_NAME>",
  "url": "https://<YOUR_DOMAIN>",
  "description": "<YOUR_APP_NAME> lets an AI agent read code and manage issues and pull requests in the repositories you install it on.",
  "redirect_url": "https://<YOUR_DOMAIN>/github/manifest-callback",
  "callback_urls": [
    "<PASTE_REDIRECT_URI_FROM_COMPOSIO_AUTH_CONFIG>"
  ],
  "public": true,
  "request_oauth_on_install": false,
  "hook_attributes": {
    "url": "https://<YOUR_DOMAIN>/github/webhooks",
    "active": false
  },
  "default_permissions": {
    "contents": "read",
    "metadata": "read",
    "issues": "write",
    "pull_requests": "write"
  },
  "default_events": []
}
